// The browser can only be exposed to the CLI once, but a worker-scoped browser
// may host several contexts and several tests. Bind it on first use and reuse
// the session name afterwards.
const browserSessionNames = new WeakMap<playwright.Browser, string>();

export async function runDaemonForContext(testInfo: TestInfoImpl, context: playwright.BrowserContext) {
  if (testInfo._configInternal.configCLIOverrides.debug !== 'cli')
    return false;

  const browser = context.browser()!;
  let sessionName = browserSessionNames.get(browser);
  if (!sessionName) {
    sessionName = `tw-${crypto.randomBytes(3).toString('hex')}`;
    await browser.bind(sessionName, { workspaceDir: testInfo.project.testDir });
    browserSessionNames.set(browser, sessionName);
  }

